import fs from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";

const DATA_PATH = path.join(process.cwd(), "data", "books.json");

async function readBooks() {
  try {
    const raw = await fs.readFile(DATA_PATH, "utf8");
    const books = JSON.parse(raw);
    return Array.isArray(books) ? books : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function writeBooks(books) {
  await fs.mkdir(path.dirname(DATA_PATH), { recursive: true });
  await fs.writeFile(DATA_PATH, JSON.stringify(books, null, 2) + "\n");
}

export async function listBooks() {
  return readBooks();
}

export async function getBook(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes ?? "").trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  const books = await readBooks();
  books.push(book);
  await writeBooks(books);
  return book;
}

export async function finishBook(id) {
  const books = await readBooks();
  const book = books.find((item) => item.id === id);
  if (!book) return null;
  book.status = "finished";
  book.finishedAt = book.finishedAt ?? new Date().toISOString();
  await writeBooks(books);
  return book;
}

export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <link rel="stylesheet" href="/styles.css">
</head>
<body>
  <header>
    <a class="brand" href="/">Reading list</a>
  </header>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

function bookItem(book) {
  const finished = book.status === "finished";
  return `<li class="book">
    <a href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
    <span class="author">${escapeHtml(book.author)}</span>
    ${
      finished
        ? ""
        : `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
            <button type="submit">Mark finished</button>
          </form>`
    }
  </li>`;
}

export function homePage(books) {
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");
  const list = (items, empty) =>
    items.length
      ? `<ul class="books">${items.map(bookItem).join("")}</ul>`
      : `<p class="empty">${empty}</p>`;

  return layout(
    "Reading list",
    `<section>
      <h1>Currently reading</h1>
      ${list(reading, "Nothing in progress.")}
    </section>
    <section>
      <h1>Finished</h1>
      ${list(finished, "No finished books yet.")}
    </section>
    <section>
      <h1>Add a book</h1>
      <form method="post" action="/books">
        <label>Title <input name="title" required></label>
        <label>Author <input name="author" required></label>
        <label>Notes <textarea name="notes" rows="4"></textarea></label>
        <button type="submit">Add book</button>
      </form>
    </section>`,
  );
}

export function bookPage(book) {
  const finished = book.status === "finished";
  return layout(
    book.title,
    `<article>
      <h1>${escapeHtml(book.title)}</h1>
      <p class="author">${escapeHtml(book.author)}</p>
      <p class="status">${finished ? "Finished" : "Currently reading"}</p>
      <h2>Notes</h2>
      <p class="notes">${escapeHtml(book.notes) || "No notes yet."}</p>
      ${
        finished
          ? ""
          : `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
              <button type="submit">Mark finished</button>
            </form>`
      }
      <p><a href="/">Back to list</a></p>
    </article>`,
  );
}

export function notFoundPage() {
  return layout(
    "Not found",
    `<h1>Book not found</h1><p><a href="/">Back to list</a></p>`,
  );
}

