import express from "express";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { addBook, finishBook, getBook, listBooks } from "./lib/store.js";
import { bookPage, homePage, notFoundPage } from "./lib/html.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();

app.use(express.urlencoded({ extended: false }));
app.use(express.static(path.join(__dirname, "public")));

app.get("/", async (_req, res, next) => {
  try {
    res.type("html").send(homePage(await listBooks()));
  } catch (err) {
    next(err);
  }
});

app.post("/books", async (req, res, next) => {
  try {
    const title = String(req.body.title ?? "").trim();
    const author = String(req.body.author ?? "").trim();
    if (!title || !author) {
      res.redirect("/");
      return;
    }
    const book = await addBook({
      title,
      author,
      notes: String(req.body.notes ?? ""),
    });
    res.redirect(`/books/${book.id}`);
  } catch (err) {
    next(err);
  }
});

app.get("/books/:id", async (req, res, next) => {
  try {
    const book = await getBook(req.params.id);
    if (!book) {
      res.status(404).type("html").send(notFoundPage());
      return;
    }
    res.type("html").send(bookPage(book));
  } catch (err) {
    next(err);
  }
});

app.post("/books/:id/finish", async (req, res, next) => {
  try {
    const book = await finishBook(req.params.id);
    if (!book) {
      res.status(404).type("html").send(notFoundPage());
      return;
    }
    res.redirect(`/books/${book.id}`);
  } catch (err) {
    next(err);
  }
});

app.use((_req, res) => {
  res.status(404).type("html").send(notFoundPage());
});

app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).type("html").send("Something went wrong.");
});

const port = Number(process.env.PORT) || 3000;

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  app.listen(port, () => {
    console.log(`Reading list at http://localhost:${port}`);
  });
}

export default app;

